#!/usr/bin/env python3
"""Probe which PDF libraries and CLI tools are available."""
import importlib
import shutil

libs = ["pypdf", "PyPDF2", "pypdfium2", "fitz", "pdfplumber", "reportlab"]
for lib in libs:
    try:
        importlib.import_module(lib)
        print(f"LIB {lib}: available")
    except Exception as exc:
        print(f"LIB {lib}: unavailable ({type(exc).__name__})")

tools = ["qpdf", "pdftk", "pdftotext", "gs", "mutool", "pdfunite"]
for tool in tools:
    path = shutil.which(tool)
    print(f"TOOL {tool}: {path if path else 'unavailable'}")

